function esTx(slug, group){
  if (slug === 'laminate') return esLamiPage(group);
  const x = ES_TX[slug];
  const blocks = [
    blk('c_subhero', { img:ES(x.heroImg), en:x.en, t:x.title, d:x.desc, crumb:`HOME  >  ${group}  >  ${x.title}` }),
    blk('c_treat', { img:ES(x.img), lab:x.en, t:x.lead.replace('\n',' '), d:x.d, pts:x.pts, btn:'상담 예약하기', side:'left' }),
    blk('c_points', { lab:'POINT', t:`e-스타치과 ${x.title}, 이런 점이 다릅니다`, s:'', items:x.points.map(([icon,t,d])=>({icon,t,d})) }),
    blk('c_steps', { lab:'PROCESS', t:`${x.title} 치료 과정`, items:x.steps.map(([t,d])=>({t,d})) })
  ];
  if (x.extra) x.extra().forEach(b => blocks.push(b));
  if (x.ba) blocks.push(blk('c_ba', { lab:'BEFORE & AFTER', t:x.baT || `${x.title} 치료 사례`, s:x.baSub || '신촌 e-스타치과에서 실제 치료한 사례입니다', items:esBaItems(x.ba) }));
  blocks.push(blk('c_faq', { lab:'FAQ', t:`${x.title} 자주 묻는 질문`, items:x.faq.map(([q,a])=>({q,a})) }));
  blocks.push(blk('c_cta', { t:`${x.title} 상담이 필요하신가요?`, s:'전화 한 통으로 진료 예약과 치료 상담이 가능합니다', btn:'전화 상담하기' }));
  return { id:'pg-' + slug, slug, title:x.title, blocks };
}
